with open(data_file) as f:
    demos = json.load(f)

def find_minority_and_majority(inp):
    """Find minority and majority colors based on grid-wide counts"""
    global_c = Counter()
    for row in inp:
        for x in row:
            global_c[x] += 1

    majority = max(global_c, key=global_c.get)
    minority = min(global_c, key=global_c.get)
    return majority, minority, dict(sorted(global_c.items(), key=lambda x: -x[1]))[:5]

def transform_grid(inp_rows):
    """Fill between minority-color anchors with 3s"""
    majority, minority, counts = find_minority_and_majority(inp_rows)
    out_rows = []

    for row in inp_rows:
        out_row = []
        j = 0
        while j < len(row):
            if row[j] == minority:
                # Found an anchor - now fill pillars of majority between two minority anchors with 3
                while j < len(row) and row[j] == majority:
                    out_row.append(3)
                    j += 1
                out_row.append(minority)
            else:
                out_row.append(row[j])
                j += 1
        out_rows.append(out_row)

    return out_rows

